var ROWS=[{"n": "Combat Step by Step Cards", "s": "esk", "sub": "Deck", "tl": [["Cards", 3]], "p": ["Identical cards that list the order of combat from the rulebook. Printable versions are available."], "tx": "combat step by step cards deck identical cards that list the order of combat from the rulebook. printable versions are available."}, {"n": "Condition Cards", "s": "esk", "sub": "Deck", "tl": [["Cards", 14]], "p": ["Cards that describe conditions affecting creatures. A player whose character has a condition keeps the card as a reminder and returns it when the condition ends. Use printed copies or a virtual tabletop."], "tx": "condition cards deck cards that describe conditions affecting creatures. a player whose character has a condition keeps the card as a reminder and returns it when the condition ends. use printed copies or a virtual tabletop."}, {"n": "Condition Cards", "s": "screendungeonkit", "sub": "Deck", "tl": [["Cards", 15]], "p": ["Double-sided cards for tracking conditions on your players' characters. Use printed copies or a virtual tabletop."], "tx": "condition cards deck double-sided cards for tracking conditions on your players' characters. use printed copies or a virtual tabletop."}, {"n": "Deck of Illusions", "s": "dmg14", "sub": "Deck", "tl": [["Cards", 33]], "p": ["A full deck has 34 cards. It works only if drawn at random. As an action, throw a drawn card within 30 feet. A harmless lifelike illusion of its creatures appears until dispelled. Within 120 feet and in sight, move it up to 30 feet from the card as an action. A DC 15 Intelligence (Investigation) check reveals it."], "tx": "deck of illusions deck a full deck has 34 cards. it works only if drawn at random. as an action, throw a drawn card within 30 feet. a harmless lifelike illusion of its creatures appears until dispelled. within 120 feet and in sight, move it up to 30 feet from the card as an action. a dc 15 intelligence (investigation) check reveals it."}, {"n": "Deck of Illusions", "s": "dmg", "sub": "Deck", "tl": [["Cards", 33]], "p": ["A full deck has 34 cards. It works only if drawn at random. As a Magic action, throw a card within 30 feet to make a harmless lifelike illusion of its creature. Move it up to 30 feet as a Magic action while within 120 feet. A Study action and DC 15 Intelligence (Investigation) check reveals it."], "tx": "deck of illusions deck a full deck has 34 cards. it works only if drawn at random. as a magic action, throw a card within 30 feet to make a harmless lifelike illusion of its creature. move it up to 30 feet as a magic action while within 120 feet. a study action and dc 15 intelligence (investigation) check reveals it."}, {"n": "Deck of Many More Things", "s": "bmt", "sub": "Deck", "tl": [["Cards", 66]], "p": ["Forty-four extra cards, often mixed with a Deck of Many Things. Most help you and about a third are dangerous. Declare how many cards you will draw, then draw at random, each within 1 hour of the last. Extra cards do nothing. Each card acts at once, then returns. The Fool and Jester do not return."], "tx": "deck of many more things deck forty-four extra cards, often mixed with a deck of many things. most help you and about a third are dangerous. declare how many cards you will draw, then draw at random, each within 1 hour of the last. extra cards do nothing. each card acts at once, then returns. the fool and jester do not return."}, {"n": "Deck of Many More Things", "s": "dmtcrg", "sub": "Deck", "tl": [["Cards", 66]], "p": ["Describes all 66 cards of the Deck of Many More Things set. Each card has an illustration, symbols, an overall meaning, and upright and reversed readings. Each reading offers five signifiers: a person, a creature or trap, a place, a treasure, and a situation. Adventure spreads draw on all five to outline an adventure."], "tx": "deck of many more things deck describes all 66 cards of the deck of many more things set. each card has an illustration, symbols, an overall meaning, and upright and reversed readings. each reading offers five signifiers: a person, a creature or trap, a place, a treasure, and a situation. adventure spreads draw on all five to outline an adventure."}, {"n": "Deck of Many Morsels", "s": "hfdomm", "sub": "Deck", "tl": [["Cards", 52]], "p": ["Heroes' Feast: a deck of D&D-themed snack and drink recipes from across the multiverse, previously known only to in-game characters. They are easy to prepare with ingredients found in the real world and are meant to add to the social side of game night."], "tx": "deck of many morsels deck heroes' feast: a deck of d&d-themed snack and drink recipes from across the multiverse, previously known only to in-game characters. they are easy to prepare with ingredients found in the real world and are meant to add to the social side of game night."}, {"n": "Deck of Many Things", "s": "bmt", "sub": "Deck", "tl": [["Cards", 22]], "p": ["The DM can make each card a standalone item with its own property. A character who finds one card can still use it. This suits a quest to find the whole deck, where each card found grants an ability for the search. Once the heroes assemble the deck, they can draw from it normally in a climactic scene."], "tx": "deck of many things deck the dm can make each card a standalone item with its own property. a character who finds one card can still use it. this suits a quest to find the whole deck, where each card found grants an ability for the search. once the heroes assemble the deck, they can draw from it normally in a climactic scene."}, {"n": "Deck of Many Things", "s": "dmg14", "sub": "Deck", "tl": [["Cards", 22]], "p": ["A box holds 13 cards (75 percent chance) or 22. Declare how many cards you will draw, then draw at random, each within 1 hour of the last. Extra cards do nothing. Each card acts when drawn, then returns. The Fool and Jester do not return. Flames brings a devil's open enmity and Rogue a friend's secret betrayal."], "tx": "deck of many things deck a box holds 13 cards (75 percent chance) or 22. declare how many cards you will draw, then draw at random, each within 1 hour of the last. extra cards do nothing. each card acts when drawn, then returns. the fool and jester do not return. flames brings a devil's open enmity and rogue a friend's secret betrayal."}, {"n": "Deck of Many Things", "s": "dmg", "sub": "Deck", "tl": [["Cards", 22]], "p": ["A box holds 13 cards (75 percent) or 22. Declare how many cards you will draw, then draw at random, each within 1 hour of the last. Extra cards do nothing. Each card acts when drawn, then returns. The Fool and Jester do not return, so reroll if either comes up again."], "tx": "deck of many things deck a box holds 13 cards (75 percent) or 22. declare how many cards you will draw, then draw at random, each within 1 hour of the last. extra cards do nothing. each card acts when drawn, then returns. the fool and jester do not return, so reroll if either comes up again."}, {"n": "Deck of Many Things (13 Cards)", "s": "dmg14", "sub": "Deck", "tl": [["Cards", 13]], "p": [], "tx": "deck of many things (13 cards) deck "}, {"n": "Deck of Many Things (13 Cards)", "s": "dmg", "sub": "Deck", "tl": [["Cards", 13]], "p": [], "tx": "deck of many things (13 cards) deck "}, {"n": "Deck of Several Things", "s": "llk", "sub": "Deck", "tl": [["Cards", 22]], "p": ["A pouch holds 22 metal cards with raised-dot designs. Declare how many cards you will draw, then draw at random, each within 1 hour of the last. Extra cards do nothing. Each card acts when drawn, then returns. The Fool and Jester do not return. Effects work only within this adventure."], "tx": "deck of several things deck a pouch holds 22 metal cards with raised-dot designs. declare how many cards you will draw, then draw at random, each within 1 hour of the last. extra cards do nothing. each card acts when drawn, then returns. the fool and jester do not return. effects work only within this adventure."}, {"n": "Deck of Wonder", "s": "bmt", "sub": "Deck", "tl": [["Cards", 22]], "p": ["Cards that grant minor boons and penalties. Decks have 13 cards (75 percent) or 22. Declare how many cards you will draw, then draw at random, each within 1 hour of the last, or the rest fly out and act at once. Extra cards do nothing. Each card acts when drawn, then returns. The Mystery card does not return."], "tx": "deck of wonder deck cards that grant minor boons and penalties. decks have 13 cards (75 percent) or 22. declare how many cards you will draw, then draw at random, each within 1 hour of the last, or the rest fly out and act at once. extra cards do nothing. each card acts when drawn, then returns. the mystery card does not return."}, {"n": "Elder Runes Deck", "s": "wdmm", "sub": "Deck", "tl": [["Cards", 9]], "p": ["Elder runes work like the symbol spell. Draw a card to learn which rune appears. Each has a boon and a bane effect, chosen by its creator or by a die (odd is bane, even is boon). It targets creatures within 60 feet, then vanishes. Boons allow no save. Halaster's banes use spell save DC 22."], "tx": "elder runes deck deck elder runes work like the symbol spell. draw a card to learn which rune appears. each has a boon and a bane effect, chosen by its creator or by a die (odd is bane, even is boon). it targets creatures within 60 feet, then vanishes. boons allow no save. halaster's banes use spell save dc 22."}, {"n": "Features Deck", "s": "dmtcrg", "sub": "Deck", "tl": [["Cards", 44]], "p": ["Part of the dungeon spread, a quick way to build dungeon adventures. Split the Deck of Many More Things into locations, features, and an optional story deck. Use the literal meanings of location and feature cards. Features are the creatures, treasures, and other things characters find in each location."], "tx": "features deck deck part of the dungeon spread, a quick way to build dungeon adventures. split the deck of many more things into locations, features, and an optional story deck. use the literal meanings of location and feature cards. features are the creatures, treasures, and other things characters find in each location."}, {"n": "Fragments of Suffering", "s": "crcotn", "sub": "Deck", "tl": [["Cards", 9]], "p": ["These cards are given to players whose characters gain Fragments of Suffering in chapter 6. See that chapter for the rules. Printable cards are in appendix D."], "tx": "fragments of suffering deck these cards are given to players whose characters gain fragments of suffering in chapter 6. see that chapter for the rules. printable cards are in appendix d."}, {"n": "Geomorph Cards", "s": "screendungeonkit", "sub": "Deck", "tl": [["Cards", 36]], "p": ["Cards for planning a dungeon during prep or improvising a map mid-play. Use printed copies or a virtual tabletop."], "tx": "geomorph cards deck cards for planning a dungeon during prep or improvising a map mid-play. use printed copies or a virtual tabletop."}, {"n": "Hazard Cards", "s": "screendungeonkit", "sub": "Deck", "tl": [["Cards", 3]], "p": ["Double-sided cards for tracking hazards your players have met. Use printed copies or a virtual tabletop."], "tx": "hazard cards deck double-sided cards for tracking hazards your players have met. use printed copies or a virtual tabletop."}, {"n": "Initiative Cards", "s": "esk", "sub": "Deck", "tl": [["Cards", 9]], "p": ["After everyone rolls initiative, hand out these numbered cards from highest to lowest count. The highest roller gets card 1 and acts first, the next gets 2, and so on. Keep the cards for the creatures you run."], "tx": "initiative cards deck after everyone rolls initiative, hand out these numbered cards from highest to lowest count. the highest roller gets card 1 and acts first, the next gets 2, and so on. keep the cards for the creatures you run."}, {"n": "Initiative Cards", "s": "screendungeonkit", "sub": "Deck", "tl": [["Cards", 9]], "p": ["Cards for tracking initiative order. Use printed copies or a virtual tabletop."], "tx": "initiative cards deck cards for tracking initiative order. use printed copies or a virtual tabletop."}, {"n": "Locations Deck", "s": "dmtcrg", "sub": "Deck", "tl": [["Cards", 11]], "p": ["Part of the dungeon spread, a quick way to build dungeon adventures. Split the Deck of Many More Things into locations, features, and an optional story deck. Use the literal meanings of location cards, which describe potential places in the dungeon."], "tx": "locations deck deck part of the dungeon spread, a quick way to build dungeon adventures. split the deck of many more things into locations, features, and an optional story deck. use the literal meanings of location cards, which describe potential places in the dungeon."}, {"n": "Magic Charm Cards", "s": "misc14", "sub": "Deck", "tl": [["Cards", 1]], "p": ["Each card describes a special charm. Give it to the player whose character receives the charm. Take it back when the charm ends for that character."], "tx": "magic charm cards deck each card describes a special charm. give it to the player whose character receives the charm. take it back when the charm ends for that character."}, {"n": "Magic Item Cards", "s": "misc14", "sub": "Deck", "tl": [["Cards", 36]], "p": ["When the characters gain and identify a magic item, give the matching card to the player whose character holds it. That player keeps it for reference until the item is used up or leaves the character's possession."], "tx": "magic item cards deck when the characters gain and identify a magic item, give the matching card to the player whose character holds it. that player keeps it for reference until the item is used up or leaves the character's possession."}, {"n": "Medals of Merit", "s": "crcotn", "sub": "Deck", "tl": [["Cards", 8]], "p": ["These cards are handed to players whose characters win Medals of Merit in chapter 1. See that chapter for the contest rules. Printable cards are in appendix C."], "tx": "medals of merit deck these cards are handed to players whose characters win medals of merit in chapter 1. see that chapter for the contest rules. printable cards are in appendix c."}, {"n": "Quest Cards", "s": "misc14", "sub": "Deck", "tl": [["Cards", 9]], "p": ["When a new quest opens to the characters, give its card to the players. Take it back when the characters finish the quest or decide to drop it."], "tx": "quest cards deck when a new quest opens to the characters, give its card to the players. take it back when the characters finish the quest or decide to drop it."}, {"n": "Roleplaying Cards", "s": "wbtw", "sub": "Deck", "tl": [["Cards", 30]], "p": ["These pages give easy-to-use card versions of Appendix D from The Wild Beyond the Witchlight. The appendices have printable versions."], "tx": "roleplaying cards deck these pages give easy-to-use card versions of appendix d from the wild beyond the witchlight. the appendices have printable versions."}, {"n": "Secrets Deck", "s": "wdmm", "sub": "Deck", "tl": [["Cards", 18]], "p": ["Cards handed to players when their characters learn reliable facts about Halaster and Undermountain. After 4 hours in the Yawning Portal, each character makes a DC 20 Intelligence (Investigation) or Wisdom (Insight) check. On a success, the player draws a card and keeps it. When an NPC knows a fact, a player draws a card for it."], "tx": "secrets deck deck cards handed to players when their characters learn reliable facts about halaster and undermountain. after 4 hours in the yawning portal, each character makes a dc 20 intelligence (investigation) or wisdom (insight) check. on a success, the player draws a card and keeps it. when an npc knows a fact, a player draws a card for it."}, {"n": "Sidekick Cards", "s": "misc14", "sub": "Deck", "tl": [["Cards", 9]], "p": ["A sidekick is a special character who joins your party. There are three types. Expert is an agile jack of all trades. Spellcaster casts spells to harm foes or heal allies. Warrior is a martial companion who attacks foes or defends allies. The DM assigns or lets you choose the type. You and the DM decide who controls the sidekick."], "tx": "sidekick cards deck a sidekick is a special character who joins your party. there are three types. expert is an agile jack of all trades. spellcaster casts spells to harm foes or heal allies. warrior is a martial companion who attacks foes or defends allies. the dm assigns or lets you choose the type. you and the dm decide who controls the sidekick."}, {"n": "Story Deck", "s": "dmtcrg", "sub": "Deck", "tl": [["Cards", 10]], "p": ["The optional third deck of the dungeon spread. Use it to build a prelude to the dungeon, reading its cards with their full symbolic meaning. To dive straight into action, skip the story steps and leave this deck out."], "tx": "story deck deck the optional third deck of the dungeon spread. use it to build a prelude to the dungeon, reading its cards with their full symbolic meaning. to dive straight into action, skip the story steps and leave this deck out."}, {"n": "Tarokka Deck", "s": "cos", "sub": "Deck", "tl": [["Cards", 54]], "p": ["A Vistani seer foretells the future with it. Only Vistani blood can imbue it with prophecy, and it must be wrapped in silk in a wooden box when unused. It has 54 cards. Forty common cards form four suits (swords, coins, stars, glyphs) numbered one to nine plus a master. Fourteen high deck cards take precedence."], "tx": "tarokka deck deck a vistani seer foretells the future with it. only vistani blood can imbue it with prophecy, and it must be wrapped in silk in a wooden box when unused. it has 54 cards. forty common cards form four suits (swords, coins, stars, glyphs) numbered one to nine plus a master. fourteen high deck cards take precedence."}, {"n": "Tarokka Deck", "s": "rhw", "sub": "Deck", "tl": [["Cards", 54]], "p": ["A prop for fortune-telling scenes with 54 cards. Forty common cards form four suits (coins, glyphs, stars, swords) numbered one to nine plus a master. Fourteen high deck cards take precedence in a reading. A reading lays out five cards for focus, past, opposition, future, and aid. Playing cards can substitute for it."], "tx": "tarokka deck deck a prop for fortune-telling scenes with 54 cards. forty common cards form four suits (coins, glyphs, stars, swords) numbered one to nine plus a master. fourteen high deck cards take precedence in a reading. a reading lays out five cards for focus, past, opposition, future, and aid. playing cards can substitute for it."}, {"n": "Tarot Deck", "s": "td", "sub": "Deck", "tl": [["Cards", 78]], "p": ["A reader and a seeker traditionally do a reading, though you can swap roles or read for yourself. Start with a question and let a five-card reading unfold. The Major Arcana (0 to 21) show life lessons. The 56 Minor Arcana cards show passing highs and lows, and their four suits map to D&D abilities."], "tx": "tarot deck deck a reader and a seeker traditionally do a reading, though you can swap roles or read for yourself. start with a question and let a five-card reading unfold. the major arcana (0 to 21) show life lessons. the 56 minor arcana cards show passing highs and lows, and their four suits map to d&d abilities."}, {"n": "Trickster Gods of Omu", "s": "toa", "sub": "Deck", "tl": [["Cards", 9]], "p": ["See the Spirits of the Nine Trickster Gods section of the adventure for details."], "tx": "trickster gods of omu deck see the spirits of the nine trickster gods section of the adventure for details."}];
